async function loadExcel(filePath) {
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.readFile(filePath);
  const sheets = [];

  for (const ws of wb.worksheets) { // one worksheet = one feature; each is partitioned independently
    const colMap = {};
    // resolve columns by HEADER TEXT, not fixed position — testers reorder columns between sheets
    ws.getRow(1).eachCell((cell, col) => {
      const h = String(cell.value || '').toLowerCase().trim();
      if (h.includes('scenario')) colMap.scenario = col;
      if (h.includes('expected') && !h.includes('actual')) colMap.expectedResult = col; // exclude 'actual' so an Actual-vs-Expected header isn't mis-bound to expected
      if (h.includes('actual')) colMap.actualResult = col;
      if (h === 'status') colMap.status = col;
    });

    const allTcs = [];
    for (let r = 2; r <= ws.rowCount; r++) { // start at row 2 — row 1 is the header just consumed
      const row = ws.getRow(r);
      const rawStatus = String(row.getCell(colMap.status || 7).value || '').trim(); // fall back to column 7 if no 'status' header was found; coerce/blank-guard before comparing
      allTcs.push({ /* scenario, expectedResult, actualResult, ... */
        status: rawStatus, isPassed: rawStatus.toUpperCase() === 'PASS' }); // strict equality to PASS — anything else (FAIL, blank, 'passed ') is treated as needs-review
    }

    sheets.push({
      sheetName: ws.name,
      passedTcs: allTcs.filter(tc => tc.isPassed),
      reviewTcs: allTcs.filter(tc => !tc.isPassed),
    });
  }
  return sheets;
}

async function generateACsFromPassed(feature) {
  if (feature.passedTcs.length === 0) return { criteria: [], sourceTcCount: 0 }; // no passes on this tab => no ACs to build; skip the LLM call entirely

  const tcBlock = feature.passedTcs.map(tc =>
    `[${tc.tcId}] ${tc.scenario}\n  Precondition: ${tc.precondition}\n  Expected: ${tc.expectedResult}`
  ).join('\n\n');

  const prompt = `You are a QA analyst generating acceptance criteria
from verified (PASSED) test cases.

${tcBlock}

Generate a JSON object with a "description" and a "criteria" array,
each entry: { scenarioName, given, when, then }.
Merge test cases that test the same behaviour into a single AC.`;

  const response = await callGeminiFlash(prompt, { temperature: 0.2, maxTokens: 4096 }); // temp 0.2: near-deterministic; ACs must restate behaviour faithfully, not paraphrase creatively
  if (!response.answer) return buildRuleBasedACs(feature); // empty model response -> deterministic fallback, so an LLM outage never blocks the document

  const parsed = parseLLMJson(response.answer);
  if (!parsed) return buildRuleBasedACs(feature); // unparseable JSON -> same fallback; degrade quality, never fail

  return { featureLabel: feature.featureLabel, description: parsed.description,
    criteria: parsed.criteria.map((c, i) => ({ acId: `AC-${i + 1}`, ...c })), // assign stable AC-1, AC-2... ids ourselves rather than trusting the model to number them
    sourceTcCount: feature.passedTcs.length };
}

async function generateReviewFromFailed(feature) {
  if (feature.reviewTcs.length === 0) return { criteria: [], sourceTcCount: 0 }; // no failures/skips on this tab => nothing to review

  const tcBlock = feature.reviewTcs.map(tc =>
    `[${tc.tcId}] ${tc.scenario}\n  Status: ${tc.status}\n  Expected: ${tc.expectedResult}\n  Actual: ${tc.actualResult}\n  Comments: ${tc.comments}`
  ).join('\n\n');

  const prompt = `These test cases did NOT pass. Generate a JSON object
with "description" and a "criteria" array — each entry in Given/When/Then
form plus "actualResult", "comments", "originalStatus".
Do NOT merge scenarios — each failed TC should be its own entry.
Preserve the actual result and comments — do NOT fabricate.`;

  const response = await callGeminiFlash(prompt, { temperature: 0.2, maxTokens: 4096 }); // same low temp; the prompt forbids merging and forbids fabricating actual/comments
  if (!response.answer) return buildRuleBasedReview(feature); // deterministic fallback keeps every failed TC in front of a human even without the LLM

  const parsed = parseLLMJson(response.answer); // tolerant parse of the model JSON
  return parsed ? { ...feature, criteria: parsed.criteria } : buildRuleBasedReview(feature);
}

function buildRuleBasedACs(feature) {
  return {
    featureLabel: feature.featureLabel,
    description: `The ${feature.featureLabel} feature provides the capabilities described below, as verified by ${feature.passedTcs.length} passed test cases.`,
    criteria: feature.passedTcs.map((tc, i) => ({ // one AC per passed row, straight mapping — no model, so output is fully deterministic
      acId: `AC-${i + 1}`,
      scenarioName: tc.scenario,
      given: tc.precondition || 'the user is logged into the application', // precondition -> Given; default to a sane baseline when the row left it blank
      when: tc.userPrompt || tc.expectedResult, // action -> When; if no explicit action was captured, reuse the expected result as the trigger
      then: tc.expectedResult,
    })),
    sourceTcCount: feature.passedTcs.length,
  };
}

// AC Document — the 'confirmed behaviour' artifact, built from PASS rows only
const acMd = buildACMarkdown(acFeatures);
fs.writeFileSync(path.join(outputDir, `TC_AC_Document_${ts}.md`), acMd);
fs.writeFileSync(path.join(outputDir, `TC_AC_Document_${ts}.json`),
  JSON.stringify({ type: 'acceptance-criteria', features: acFeatures }, null, 2));

// Review Document — the 'needs a human ruling' artifact, one entry per non-passing test
const rvMd = buildReviewMarkdown(reviewFeatures);
fs.writeFileSync(path.join(outputDir, `TC_Review_Document_${ts}.md`), rvMd);

if (generateWord) {
  await buildACWord(acFeatures, path.join(outputDir, `TC_AC_Document_${ts}.docx`));
  await buildReviewWord(reviewFeatures, path.join(outputDir, `TC_Review_Document_${ts}.docx`)); // the review docx is the one carrying the Valid Bug / Invalid Test / Needs Info tick-boxes
}
